// Original unpublished discovery is actor-selected draft state, never the shell's
// canonical file or another actor's draft. No new permission or serving authority.
struct PgUnpublishedView{metadata:Option<serde_json::Value>,content:Option<serde_json::Value>,draft_id:String,raw_draft:serde_json::Value}
struct PgUnpublishedPage{space:String,id:String,owner:PgUnpublishedView,samples:Vec<PgUnpublishedView>}
struct PgUnpublishedPlan{source:Identity,attestation_sha:String,actor:String,session:String,pages:Vec<PgUnpublishedPage>}
async fn pg_unpublished_view(original:&mut StoppedPgVerificationSource<'_>,auth:&crate::auth::middleware::AuthUser,space:&str,id:&str,base:&serde_json::Value)->anyhow::Result<PgUnpublishedView>{
 let selected=pg_expected_access(crate::spaces::documents::readable_discovery_draft(original.conn,auth,space,id).await)?;
 let Some(draft)=selected else{return Ok(PgUnpublishedView{metadata:None,content:None,draft_id:String::new(),raw_draft:serde_json::Value::Null})};
 let principal=crate::spaces::access::principal_from_auth(auth).map_err(|_|fail("Original unpublished actor expired"))?;
 let metadata_allowed=pg_expected_access(crate::spaces::access::resolve_page_access(original.conn,principal,space,id,crate::spaces::access::PageOperation::InspectMetadata,crate::spaces::access::Purpose::Routine).await)?.is_some();
 let principal=crate::spaces::access::principal_from_auth(auth).map_err(|_|fail("Original unpublished actor expired"))?;
 let content_allowed=pg_expected_access(crate::spaces::access::resolve_page_access(original.conn,principal,space,id,crate::spaces::access::PageOperation::View,crate::spaces::access::Purpose::Routine).await)?.is_some();
 let content=if content_allowed{Some(serde_json::json!({"id":id,"title":draft.title,"content":crate::spaces::documents::discovery_draft_content(&draft).map_err(|e|anyhow::anyhow!("Original selected draft projection unavailable:{e:?}"))?}))}else{None};
 let metadata=if metadata_allowed{let mut value=base.clone();value["title"]=draft.title.clone().into();value["icon"]=serde_json::to_value(&draft.icon)?;value["cover_image"]=serde_json::to_value(&draft.cover_image)?;value["draft_id"]=draft.id.clone().into();value["identifier_edit_allowed"]=crate::spaces::page_metadata::edit_allowed(original.conn,auth,space,id).await.map_err(|e|anyhow::anyhow!("Original draft identifier capability unavailable:{e:?}"))?.into();value["maintenance_edit_allowed"]=crate::spaces::maintenance::edit_allowed(original.conn,auth,space,id).await.map_err(|e|anyhow::anyhow!("Original draft maintenance capability unavailable:{e:?}"))?.into();Some(value)}else{None};
 let rows=crate::spaces::document_deletion::rows(original.conn,"SELECT * FROM document_drafts WHERE id=$1 AND space_id=$2 AND document_id=$3",&[&draft.id,space,id]).await.map_err(|e|anyhow::anyhow!(e))?;ensure!(rows.len()==1,"Original selected draft raw identity absent");let raw_draft=serde_json::to_value(&rows)?;ensure!(serde_json::to_vec(&raw_draft)?.len()<=8*1024*1024,"Original selected raw draft exceeds8MiB");
 Ok(PgUnpublishedView{metadata,content,draft_id:draft.id,raw_draft})
}
impl PgUnpublishedPlan{
 async fn capture(original:&mut StoppedPgVerificationSource<'_>,published:&PgCanonicalPagePlan,audiences:&PgCanonicalAudiencePlan)->anyhow::Result<Self>{
 use sqlx::Row;audiences.fence(original).await?;published.fence(original)?;let rows=sqlx::query("SELECT id,space_id,created_at,updated_at FROM documents WHERE published_at IS NULL AND archived_at IS NULL AND deleted_at IS NULL ORDER BY space_id,id LIMIT 257").fetch_all(&mut *original.conn).await?;ensure!(published.pages.len().checked_add(rows.len()).is_some_and(|n|n<=256),"Complete application plan exceeds256 active published/unpublished pages");
 let auth=crate::auth::middleware::AuthUser{claims:original.admin.claims.clone(),api_key_scopes:None};let mut pages=Vec::new();let mut total=0usize;
 for row in rows{let id:String=row.try_get("id")?;let space:String=row.try_get("space_id")?;let base=serde_json::json!({"id":id,"space_id":space,"created_at":row.try_get::<String,_>("created_at")?,"updated_at":row.try_get::<String,_>("updated_at")?,"published_at":null});let owner=pg_unpublished_view(original,&auth,&space,&id,&base).await?;ensure!(owner.metadata.is_some()&&owner.content.is_some(),"Original administrator cannot certify selected unpublished discovery");let mut samples=Vec::new();for sample in &audiences.samples{samples.push(pg_unpublished_view(original,&sample.credential.auth,&space,&id,&base).await?);}for view in std::iter::once(&owner).chain(samples.iter()){total=pg_probe_account(total,&serde_json::json!({"metadata":view.metadata,"content":view.content,"draft":view.raw_draft}))?;}pages.push(PgUnpublishedPage{space,id,owner,samples});}
 let plan=Self{source:original.root_identity()?,attestation_sha:digest(&original.serving.proof.raw_attestation),actor:original.admin.claims.sub.clone(),session:original.admin.claims.sid.clone(),pages};plan.fence(original,audiences).await?;Ok(plan)
 }
 async fn fence(&self,original:&mut StoppedPgVerificationSource<'_>,audiences:&PgCanonicalAudiencePlan)->anyhow::Result<()>{audiences.fence(original).await?;ensure!(self.source==original.root_identity()?&&self.attestation_sha==digest(&original.serving.proof.raw_attestation)&&self.actor==original.admin.claims.sub&&self.session==original.admin.claims.sid,"Original unpublished source context differs");for page in &self.pages{ensure!(page.samples.len()==audiences.samples.len(),"Original unpublished audience closure differs");for view in std::iter::once(&page.owner).chain(page.samples.iter()){if !view.draft_id.is_empty(){let rows=crate::spaces::document_deletion::rows(original.conn,"SELECT * FROM document_drafts WHERE id=$1 AND space_id=$2 AND document_id=$3",&[&view.draft_id,&page.space,&page.id]).await.map_err(|e|anyhow::anyhow!(e))?;ensure!(serde_json::to_value(rows)?==view.raw_draft,"Original selected unpublished draft identity/bytes/digest differ");}}}original.physical()?;Ok(())}
}
fn pg_verify_unpublished_reply(expected:Option<&serde_json::Value>,status:reqwest::StatusCode,actual:&serde_json::Value,metadata:bool)->anyhow::Result<()>{if let Some(expected)=expected{ensure!(status==reqwest::StatusCode::OK,"Original permitted unpublished route refused");if metadata{for(key,value)in expected.as_object().context("Original unpublished metadata malformed")?{ensure!(actual.get(key)==Some(value),"Original unpublished metadata/draft/capability differs");}}else{ensure!(actual==expected&&actual.get("published_source_digest").is_none()&&actual.get("published_metadata").is_none(),"Original selected unpublished body/presentation or publication fields differ");}}else{ensure!(matches!(status.as_u16(),401|403|404),"Original denied unpublished audience received discovery state");}Ok(())}
async fn pg_verify_unpublished(original:&mut StoppedPgVerificationSource<'_>,plan:&PgUnpublishedPlan,audiences:&PgCanonicalAudiencePlan,process:&mut std::process::Child,address:std::net::SocketAddr,client:&reqwest::Client,token:&str)->anyhow::Result<()>{plan.fence(original,audiences).await?;for page in &plan.pages{let prefix=format!("/spaces/{}/documents/{}",urlencoding::encode(&page.space),urlencoding::encode(&page.id));for(suffix,metadata)in [("",true),("/content",false)]{let uri=format!("{prefix}{suffix}");let(status,value)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,Some(token),&uri)).await?;pg_verify_unpublished_reply(if metadata{page.owner.metadata.as_ref()}else{page.owner.content.as_ref()},status,&value,metadata)?;for(sample,view)in audiences.samples.iter().zip(&page.samples){let(status,value)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,Some(&sample.credential.bearer),&uri)).await?;pg_verify_unpublished_reply(if metadata{view.metadata.as_ref()}else{view.content.as_ref()},status,&value,metadata)?;}let(status,value)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,None,&uri)).await?;pg_verify_unpublished_reply(None,status,&value,metadata)?;}}plan.fence(original,audiences).await?;Ok(())}
#[cfg(test)]mod pg_unpublished_controls{use super::*;#[test]fn exact_draft_body_cannot_borrow_published_or_other_draft_projection(){let expected=serde_json::json!({"id":"p","title":"Original selected draft","content":"Opaque original draft"});assert!(pg_verify_unpublished_reply(Some(&expected),reqwest::StatusCode::OK,&expected,false).is_ok());for key in ["published_source_digest","published_metadata","content","id"]{let mut wrong=expected.clone();wrong[key]="foreign".into();assert!(pg_verify_unpublished_reply(Some(&expected),reqwest::StatusCode::OK,&wrong,false).is_err());}assert!(pg_verify_unpublished_reply(None,reqwest::StatusCode::OK,&expected,false).is_err());assert!(pg_verify_unpublished_reply(None,reqwest::StatusCode::FORBIDDEN,&serde_json::Value::Null,false).is_ok());}}

async fn pg_verify_preindex_private(original:&mut StoppedPgVerificationSource<'_>,audiences:&PgCanonicalAudiencePlan,process:&mut std::process::Child,address:std::net::SocketAddr,client:&reqwest::Client,token:&str,pages:&PgCanonicalPagePlan,drafts:&PgCanonicalDraftPlan)->anyhow::Result<()>{let words=pg_original_private_search_words(pages,drafts)?;ensure!(drafts.drafts.is_empty()||!words.is_empty(),"Original draft lacks distinguishing pre-index private term");let auth=crate::auth::middleware::AuthUser{claims:original.admin.claims.clone(),api_key_scopes:None};let owner=pg_expected_access(crate::spaces::access::require_current_human_read(original.conn,&auth).await)?.is_some();for word in &words{pg_audience_observation(original,audiences,process,pg_private_default_search(client,address,token,word,owner)).await?;for sample in &audiences.samples{pg_audience_observation(original,audiences,process,pg_private_default_search(client,address,&sample.credential.bearer,word,sample.global_read)).await?;}let uri=format!("/search?q={}&limit=100",urlencoding::encode(word));let(status,_)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,None,&uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous default search exposed private draft results");}Ok(())}

// An empty source has no distinguishing original body term. Exercise actual
// current-human/anonymous search on both sides of the registered rebuild anyway.
async fn pg_verify_empty_search(original:&mut StoppedPgVerificationSource<'_>,pages:&PgCanonicalPagePlan,unpublished:&PgUnpublishedPlan,audiences:&PgCanonicalAudiencePlan,process:&mut std::process::Child,address:std::net::SocketAddr,client:&reqwest::Client,token:&str,phase:&'static str)->anyhow::Result<usize>{
 if !pages.pages.is_empty()||!unpublished.pages.is_empty(){return Ok(0);}
 unpublished.fence(original,audiences).await?;let uri="/search?q=EMPTYORIGINALWORKSPACE&limit=100";let mut observed=0usize;
 let(status,value)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,Some(token),uri)).await?;ensure!(status==reqwest::StatusCode::OK&&value.as_array().is_some_and(|v|v.is_empty()),"Empty original PG workspace returned data or lost current owner search access");observed+=1;
 for sample in &audiences.samples{let(status,value)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,Some(&sample.credential.bearer),uri)).await?;if sample.global_read{ensure!(status==reqwest::StatusCode::OK&&value.as_array().is_some_and(|v|v.is_empty()),"Empty original PG audience search differs");}else{ensure!(matches!(status.as_u16(),401|403|404),"Denied empty original PG audience acquired search access");}observed+=1;}
 let(status,_)=pg_audience_observation(original,audiences,process,pg_ordinary_actual_json(client,address,None,uri)).await?;ensure!(matches!(status.as_u16(),401|403|404),"Anonymous empty PG workspace acquired search access");observed+=1;
 ensure!(observed==audiences.samples.len()+2,"Actual empty PG response closure incomplete");unpublished.fence(original,audiences).await?;eprintln!("PG_EMPTY_SEARCH_PROBE phase={phase} observed_responses={observed} sampled_current_humans={}",audiences.samples.len());Ok(observed)
}
